package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"

	"github.com/avdsn/gofuzz"
)

// Define your struct type here.
type MyStruct struct {
	Field1 string `json:"field1"`
	Field2 int    `json:"field2"`
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <struct_name> <source_file>")
		return
	}

	structName := os.Args[1]
	sourceFilePath := os.Args[2]

	// Read the content of the source file
	content, err := ioutil.ReadFile(sourceFilePath)
	if err != nil {
		fmt.Printf("Error reading file %s: %v\n", sourceFilePath, err)
		os.Exit(1)
	}

	// Parse the JSON content into a struct
	var myStruct MyStruct
	err = json.Unmarshal(content, &myStruct)
	if err != nil {
		fmt.Printf("Failed to unmarshal JSON: %v\n", err)
		os.Exit(1)
	}

	// Generate Avro schema based on the struct fields
	schema, err := gofuzz.NewSchemaBuilder()
	if err != nil {
		fmt.Printf("Error creating schema builder: %v\n", err)
		os.Exit(1)
	}
	defer schema.Close()

	for _, field := range []string{"Field1", "Field2"} {
		fieldType, ok := myStruct.(map[string]interface{})
		if !ok {
			fmt.Printf("Field '%s' not found in struct.\n", field)
			continue
		}

		avroType := gofuzz.TypeString(fieldType[field])
		if avroType == "" {
			fmt.Printf("Unsupported type for field '%s': %T\n", field, fieldType[field])
			continue
		}

		schema.AddField(field, avroType)
	}

	// Write the generated Avro schema to a file
	filePath := fmt.Sprintf("%s.avsc", structName)
	f, err := os.Create(filePath)
	if err != nil {
		fmt.Printf("Error writing schema to file %s: %v\n", filePath, err)
		os.Exit(1)
	}
	defer f.Close()

	_, err = f.WriteString(schema.String())
	if err != nil {
		fmt.Printf("Error writing schema to file %s: %v\n", filePath, err)
		os.Exit(1)
	}

	fmt.Printf("Avro schema written to %s\n", filePath)
}
```

